item.command:
/bin/bash -lc "python3 - <<'PY'
import urllib.request, hashlib, json
base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
for name in ['examples/5dfr_solv-cube_equil.pdb','examples/benchmark.py']:
    try:
        b=urllib.request.urlopen(base+name,timeout=30).read()
        print(json.dumps({'path':name,'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}))
        if name.endswith('.py'):
            lines=b.decode().splitlines()
            for i,s in enumerate(lines):
                if any(x in s for x in ['5dfr','amber99sb','tip3p','LangevinMiddle','add_option','add_argument','constraintTolerance','setConstraintTolerance']):
                    print(str(i+1)+': '+s)
    except Exception as e: print(json.dumps({'path':name,'error':str(e)}))
u='https://pypi.org/pypi/openmm/8.2.0/json'
j=json.load(urllib.request.urlopen(u,timeout=30))
print(json.dumps({'source':u,'requires_python':j['info']['requires_python'],'linux_wheels':[{'filename':x['filename'],'sha256':x['digests']['sha256']} for x in j['urls'] if 'manylinux' in x['filename']]}))
PY"

